from collections import deque
n=16
G=[[8]*n for _ in range(n)]; G[0][0]=6
for c in range(n):G[6][c]=1
for r in (9,10):
 for c in range(7,10):G[r][c]=1
for r in (10,11):
 for c in range(13,16):G[r][c]=1
for r in range(12,16):
 for c in range(4):G[r][c]=1
# background component (8-connected), seeded from the 6 marker
reach={(0,0)}; q=deque([(0,0)])
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   rr,cc=r+dr,c+dc
   if (dr or dc) and 0<=rr<n and 0<=cc<n and G[rr][cc] in (6,8) and (rr,cc) not in reach:
    reach.add((rr,cc));q.append((rr,cc))
# Find 4-connected edge-touching 1 components
seen=set(); edge_ones=set()
for r in range(n):
 for c in range(n):
  if G[r][c]==1 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));comp=[]
   while q:
    rr,cc=q.pop();comp.append((rr,cc))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=rr+dr,cc+dc
     if 0<=a<n and 0<=b<n and G[a][b]==1 and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   if any(rr in (0,n-1) or cc in (0,n-1) for rr,cc in comp): edge_ones.update(comp)
out=[row[:] for row in G]
for r in range(n):
 for c in range(n):
  if G[r][c]!=8 or (r,c) not in reach:continue
  border=(r in (0,n-1) or c in (0,n-1))
  near_edge_one=any((r+dr,c+dc) in edge_ones for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc)
  if border or near_edge_one:out[r][c]=7
print('reachable count',len(reach),'edge component sizes',[len(x) for x in []])
print('\n'.join(' '.join(map(str,row)) for row in out))

